def _fail_discovery(exc: BaseException) -> None:
    typer.echo(
        json.dumps(
            {
                "availability": "candidate_only",
                "status": "failed_closed",
                "reasonCode": "DISCOVERY_INPUT_REJECTED",
                "detail": str(exc),
            },
            sort_keys=True,
        ),
        err=True,
    )
    raise typer.Exit(code=2) from None

